def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # Lines uniformly filled with a non-background color divide the grid into panels.
    sep_rows = [r for r, row in enumerate(grid)
                if len(set(row)) == 1 and row[0] != bg]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != bg]

    def panels(n, separators):
        result, start = [], 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rows = panels(h, sep_rows)
    cols = panels(w, sep_cols)

    # Copy the non-empty panel's pattern to every other panel.
    source = max(
        ((sum(grid[r][c] != bg for r in range(r0, r1)
              for c in range(c0, c1)), ri, ci)
         for ri, (r0, r1) in enumerate(rows)
         for ci, (c0, c1) in enumerate(cols)),
        key=lambda item: item[0]
    )
    _, sri, sci = source
    r0, r1 = rows[sri]
    c0, c1 = cols[sci]
    pattern = [grid[r][c0:c1] for r in range(r0, r1)]

    out = [row[:] for row in grid]
    for a, b in rows:
        for x, y in cols:
            if (a, b, x, y) == (r0, r1, c0, c1):
                continue
            if b - a == len(pattern) and y - x == len(pattern[0]):
                for dr in range(len(pattern)):
                    out[a + dr][x:y] = pattern[dr][:]
    return out
